WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_rt_diff'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '不等距离往返', 'kp-trv-rt-diff', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "不等距离往返"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "去程和回程走的不同路线，路程不相等。必须回归原始公式 S总/T总。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“去程走盘山公路，回程抄近道走直路，距离短了 1/3”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破局"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "既然距离不同，就彻底废弃“调和平均数”公式，老老实实算总距离和总时间。"}]}, {"type": "katexBlock", "attrs": {"content": "V_{平均} = \\frac{S_1 + S_2}{T_1 + T_2} = \\frac{S_1 + S_2}{\\frac{S_1}{V_1} + \\frac{S_2}{V_2}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目, 发现去回程距离不同] --> B[利用题干比例关系, 赋出 S1 和 S2 的具体特值]\nB --> C[利用给定的 V1 和 V2, 分别算出 T1 和 T2]\nC --> D[总路程 = S1 + S2]\nD --> E[总时间 = T1 + T2]\nE --> F[平均速度 = 总路程 ÷ 总时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 去程走长路，长 60km，速度 30。回程走短路，长 40km，速度 20。求往返平均速度？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总路程：60 + 40 = 100 km。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算去程时间：60 / 30 = 2 h。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算回程时间：40 / 20 = 2 h。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总时间：2 + 2 = 4 h。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算平均速度：100 ÷ 4 = 25 km/h。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "乱套公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "看都没看题目说是走不同的路，直接套 2×30×20 / (30+20) = 24，光荣阵亡。必须看清“原路返回”四个字才能用调和公式。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果题目没给具体公里数，只说“回程距离是去程的 2/3”，自己大胆赋特值，令去程距离为 60，回程为 40。"}]}]}$$ AS jsonb), NULL, '不等距离往返的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "不等距离往返"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_rt_diff", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
